-- 099_project_scope_closeout.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_scope_closeout_versions(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),original_scope_version_id bigint NOT NULL,final_scope_version_id bigint NOT NULL,original_scope jsonb NOT NULL CHECK(jsonb_typeof(original_scope)='array'),added_scope jsonb NOT NULL CHECK(jsonb_typeof(added_scope)='array'),removed_scope jsonb NOT NULL CHECK(jsonb_typeof(removed_scope)='array'),changed_scope jsonb NOT NULL CHECK(jsonb_typeof(changed_scope)='array'),scope_explanation text NOT NULL CHECK(btrim(scope_explanation)<>''AND char_length(scope_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number)
);CREATE UNIQUE INDEX IF NOT EXISTS project_scope_closeout_one_confirmed_idx ON public.project_scope_closeout_versions(project_id)WHERE status='CONFIRMED';
CREATE OR REPLACE FUNCTION private.prevent_scope_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_SCOPE_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_scope_closeout_immutable ON public.project_scope_closeout_versions;CREATE TRIGGER project_scope_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_scope_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_scope_closeout_mutation();
ALTER TABLE public.project_scope_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_scope_closeout_select ON public.project_scope_closeout_versions;CREATE POLICY project_scope_closeout_select ON public.project_scope_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_scope_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_scope_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_scope_closeout(p_project_id bigint,p_closeout_id uuid,p_scope_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;req public.write_command_requests%ROWTYPE;first_id bigint;last_id bigint;version_no integer;state text;original_items jsonb;added_items jsonb;removed_items jsonb;changed_items jsonb;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_SCOPE_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_scope_explanation,''))=''OR char_length(p_scope_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_SCOPE_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.scope.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.scope.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_scope_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_SCOPE_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT id INTO first_id FROM public.project_execution_scope_versions WHERE project_id=p_project_id ORDER BY revision_number ASC LIMIT 1;SELECT id INTO last_id FROM public.project_execution_scope_versions WHERE project_id=p_project_id ORDER BY revision_number DESC LIMIT 1;IF first_id IS NULL OR last_id IS NULL THEN RAISE EXCEPTION'SCOPE_CLOSEOUT_REQUIRES_EXECUTION_SCOPE'USING ERRCODE='55000';END IF;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',i.work_group_id,'disciplineId',i.discipline_id,'code',w.code,'label',w.label)ORDER BY w.display_order),'[]')INTO original_items FROM public.project_execution_scope_items i JOIN public.work_ontology_work_groups w ON w.ontology_version_id=i.ontology_version_id AND w.id=i.work_group_id WHERE i.execution_scope_version_id=first_id;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',z.work_group_id,'disciplineId',z.discipline_id,'code',z.code,'label',z.label)ORDER BY z.display_order),'[]')INTO added_items FROM(SELECT i.work_group_id,i.discipline_id,w.code,w.label,w.display_order FROM public.project_execution_scope_items i JOIN public.work_ontology_work_groups w ON w.ontology_version_id=i.ontology_version_id AND w.id=i.work_group_id WHERE i.execution_scope_version_id=last_id AND NOT EXISTS(SELECT 1 FROM public.project_execution_scope_items o WHERE o.execution_scope_version_id=first_id AND o.work_group_id=i.work_group_id))z;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',z.work_group_id,'disciplineId',z.discipline_id,'code',z.code,'label',z.label)ORDER BY z.display_order),'[]')INTO removed_items FROM(SELECT i.work_group_id,i.discipline_id,w.code,w.label,w.display_order FROM public.project_execution_scope_items i JOIN public.work_ontology_work_groups w ON w.ontology_version_id=i.ontology_version_id AND w.id=i.work_group_id WHERE i.execution_scope_version_id=first_id AND NOT EXISTS(SELECT 1 FROM public.project_execution_scope_items n WHERE n.execution_scope_version_id=last_id AND n.work_group_id=i.work_group_id))z;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',v.work_group_id,'disciplineId',v.discipline_id,'code',w.code,'label',w.label,'approvedVariationCount',v.change_count,'approvedVariationValue',v.change_value)ORDER BY w.display_order),'[]')INTO changed_items FROM(SELECT ontology_version_id,work_group_id,discipline_id,count(*)change_count,sum(approved_amount)change_value FROM public.project_variations WHERE project_id=p_project_id AND status='APPROVED'GROUP BY ontology_version_id,work_group_id,discipline_id)v JOIN public.work_ontology_work_groups w ON w.ontology_version_id=v.ontology_version_id AND w.id=v.work_group_id;SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_scope_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_scope_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,first_id,last_id,original_items,added_items,removed_items,changed_items,btrim(p_scope_explanation),u,now());result:=jsonb_build_object('scopeCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'originalScopeVersionId',first_id,'finalScopeVersionId',last_id,'originalCount',jsonb_array_length(original_items),'addedCount',jsonb_array_length(added_items),'removedCount',jsonb_array_length(removed_items),'changedCount',jsonb_array_length(changed_items));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_scope_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_scope_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_SCOPE_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_scope_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('scopeCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'originalScopeVersionId',x.original_scope_version_id,'finalScopeVersionId',x.final_scope_version_id,'originalScope',x.original_scope,'addedScope',x.added_scope,'removedScope',x.removed_scope,'changedScope',x.changed_scope,'scopeExplanation',x.scope_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_scope_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_scope_closeout(bigint,uuid,text,boolean,uuid),public.get_project_scope_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_scope_closeout(bigint,uuid,text,boolean,uuid),public.get_project_scope_closeout(bigint)TO authenticated;
COMMIT;
